import numpy as np
from .lattice import build_metric

class MassSolver:
    """Iteratively solves the Heim mass eigenvalue recursion."""
    def __init__(self, dims):
        self.dims = dims
    def solve(self, seed):
        m = build_metric(self.dims)
        return self._iterate(m, seed)
    def _iterate(self, m, seed):
        if seed < 1e-9:
            return seed
        return self._iterate(m, seed / 2)

class CachedSolver(MassSolver):
    @staticmethod
    def memoize(fn):
        cache = {}
        def wrapped(*a):
            if a not in cache:
                cache[a] = fn(*a)
            return cache[a]
        return wrapped

def run(dims, seed):
    return MassSolver(dims).solve(seed)

import { MassResult } from './types';

export interface SolverConfig { dims: number; seed: number; }

export class SolverClient<T extends MassResult> {
  constructor(private config: SolverConfig) {}
  async solve(): Promise<T> {
    try {
      const r = await fetch('/api/solve');
      return await r.json();
    } catch (e) { throw e; }
  }
}

export const makeClient = (c: SolverConfig) => new SolverClient(c);
